const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const data={attendance:[['Rifqi Muhammad A','16 Nov 2026','08:03','17:12','Hadir'],['Yuna Sukmana','16 Nov 2026','07:56','17:05','Hadir'],['Andi Pratama','16 Nov 2026','08:19','—','Terlambat']],work:[['16 Nov 2026','IP-PBX','Pemeriksaan telepon ruang 102','Suara terputus saat panggilan internal','Restart ONT/router dan koneksi kembali normal'],['15 Nov 2026','Lain-lain','Instalasi driver printer','Printer laptop BTS Pajak belum terdeteksi','Instalasi driver terbaru dan uji cetak'],['14 Nov 2026','Lain-lain','Pengecekan token charger mobil','Pengisian token operasional','Pengisian berhasil, daya tercatat 103,8 kWh']],server:[['16/11/2026','Lantai 5','09:15','24°C','48%','Normal','RA'],['16/11/2026','R.610 Kaca','09:18','23°C','49%','Normal','RA'],['15/11/2026','Lantai 5','09:10','24°C','48%','Normal','RA']],reimburse:[['RB-2026-032','15 Nov 2026','Rifqi Muhammad Athallah','Galon & jilid dokumen','Rp108.000','Menunggu'],['RB-2026-031','11 Nov 2026','Andi Pratama','Perlengkapan jaringan','Rp375.000','Disetujui']],request:[['PB-2026-019','15 Nov 2026','Toner HP 85A','2 pcs','Operasional printer','Menunggu'],['PB-2026-018','10 Nov 2026','Kabel LAN Cat6','1 box','Persediaan IT','Disetujui']]};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const status=s=>`<span class="status ${['Disetujui','Hadir','Normal'].includes(s)?'done':'pending'}">${esc(s)}</span>`;const edit=(m,i)=>`<button class="edit-row" data-edit="${m}:${i}">Edit</button>`;
function render(){
 $('#attendanceRows').innerHTML=data.attendance.map((r,i)=>`<tr>${r.slice(0,4).map(x=>`<td>${esc(x)}</td>`).join('')}<td>${status(r[4])}</td><td>${edit('attendance',i)}</td></tr>`).join('');
 $('#workRows').innerHTML=data.work.map((r,i)=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}<td>${edit('work',i)} <button class="text-btn print-row" data-print="work">⎙</button></td></tr>`).join('');
 $('#serverRows').innerHTML=data.server.map((r,i)=>`<tr>${r.map((x,n)=>`<td>${n===5?status(x):esc(x)}</td>`).join('')}<td>${edit('server',i)}</td></tr>`).join('');
 ['reimburse','request'].forEach(k=>$('#'+k+'Rows').innerHTML=data[k].map((r,i)=>`<tr>${r.map((x,n)=>`<td>${n===r.length-1?status(x):esc(x)}</td>`).join('')}<td>${edit(k,i)} <button class="text-btn print-row" data-print="${k}">⎙</button></td></tr>`).join(''));
 $('#activity').innerHTML=data.work.slice(0,3).map((r,i)=>`<div class="activity-item"><span class="activity-icon">${i===0?'☎':i===1?'▣':'⚡'}</span><div><b>${esc(r[2])}</b><span>${esc(r[1])} · ${esc(r[0])}</span></div></div>`).join('');renderMonthly();
}
function renderMonthly(){const readings={};data.server.forEach(r=>{const d=Number(r[0].split('/')[0]);if(!readings[d])readings[d]=r});const names=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];$('#monthlyTemperatureRows').innerHTML=Array.from({length:30},(_,i)=>{const d=i+1,date=new Date(2026,10,i+1),weekend=[0,6].includes(date.getDay()),r=readings[d];return `<tr class="${weekend&&!r?'weekend':''} ${r?'has-reading':''}"><td>${d}</td><td>${String(d).padStart(2,'0')}/11/2026</td><td>${names[date.getDay()]}, ${d} November 2026</td>${r?`<td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>✓</td><td></td><td>${r[6]}</td>`:'<td></td><td></td><td></td><td></td><td></td><td></td><td></td>'}</tr>`}).join('');$('#monthlyWorkRows').innerHTML=data.work.map(r=>`<tr><td>Nov26</td>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('');const bad=data.server.filter(r=>r[5]!=='Normal');$('#monthlyNotes').innerHTML=bad.length?bad.map(r=>`<li>${esc(r[0])} · ${esc(r[1])}: ${esc(r[5])}</li>`).join(''):'<li>Seluruh hasil pengecekan dalam kondisi normal.</li><li>—</li><li>—</li>'}
function show(p){$$('.page').forEach(x=>x.classList.toggle('active-page',x.id===p));$$('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===p));const n={dashboard:['OVERVIEW','Selamat pagi, Rifqi'],attendance:['OPERASIONAL','Absensi'],work:['OPERASIONAL','Laporan pekerjaan'],server:['INFRASTRUKTUR','Pengecekan server'],reimburse:['KEUANGAN','Reimbursement'],request:['PENGADAAN','Pengajuan barang'],monthly:['REKAP','Laporan bulanan'],settings:['SISTEM','Pengaturan']};$('#crumb').textContent=n[p][0];$('#pageTitle').textContent=n[p][1];scrollTo(0,0)}function toast(t){$('#toast').textContent=t;$('#toast').classList.remove('hidden');setTimeout(()=>$('#toast').classList.add('hidden'),2600)}
function printDoc(m){if(m==='monthly'){print();return}const labels={attendance:'Rekap Absensi',work:'Laporan Pekerjaan',server:'Pengecekan Suhu Ruang Server',reimburse:'Surat Permohonan Reimbursement',request:'Pengajuan Barang'};if(!labels[m])return toast('Pilih modul laporan yang ingin dicetak terlebih dahulu.');const table=$('#'+m)?.querySelector('table'),w=open('','_blank','width=900,height=700');if(!w)return toast('Izinkan pop-up browser untuk mencetak laporan.');let body=table?.outerHTML||'';if(m==='reimburse')body=`<p>Kepada Yth.<br><b>Manajer terkait</b></p><p>Berikut rincian pengajuan reimbursement periode November 2026.</p>${body}<p>Demikian pengajuan ini dibuat untuk dapat diproses.</p><p style="text-align:right;margin-top:42px">Pemohon,<br><br><br><b>Administrator OPS</b></p>`;w.document.write(`<!doctype html><title>${labels[m]}</title><style>body{font-family:Arial;color:#111;margin:34px}header{border-bottom:2px solid #172b4d;padding-bottom:12px;margin-bottom:22px}h1{font-size:21px;margin:0}p{font-size:13px;line-height:1.5}table{border-collapse:collapse;width:100%;font-size:11px}th,td{border:1px solid #555;padding:8px;text-align:left;vertical-align:top}th{background:#e9edf2}.edit-row,.print-row{display:none}@page{size:A4 portrait;margin:14mm}</style><header><h1>OPS REPORT · BANGUN TJIPTA</h1><p>${labels[m]} · Periode November 2026<br>Dicetak: ${new Date().toLocaleDateString('id-ID')}</p></header>${body}`);w.document.close();setTimeout(()=>w.print(),250)}
function input(l,t,v=''){return `<label>${l}<input type="${t}" value="${esc(v)}" required></label>`}function toInput(v=''){if(/^\d{2}\/\d{2}\/\d{4}$/.test(v)){const[a,b,c]=v.split('/');return `${c}-${b}-${a}`}const m=v.match(/(\d{1,2})\s+(\w+)\s+(\d{4})/);if(!m)return '';const mo={Jan:0,Feb:1,Mar:2,Apr:3,Mei:4,Jun:5,Jul:6,Agu:7,Sep:8,Okt:9,Nov:10,Des:11}[m[2].slice(0,3)]??10;return `${m[3]}-${String(mo+1).padStart(2,'0')}-${m[1].padStart(2,'0')}`}function human(v){if(!v)return '';const[y,m,d]=v.split('-');return `${d} ${['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][Number(m)-1]} ${y}`}
function fields(m,r=[]){if(m==='server')return input('Tanggal','date',toInput(r[0]))+`<label>Ruangan<select required><option value="Lantai 5" ${r[1]==='Lantai 5'?'selected':''}>Lantai 5</option><option value="R.610 Kaca" ${r[1]==='R.610 Kaca'?'selected':''}>R.610 Kaca</option></select></label>`+input('Jam','time',r[2])+input('Suhu (°C)','number',String(r[3]||'').replace('°C',''))+input('Kelembaban (%)','number',String(r[4]||'').replace('%',''));if(m==='work')return input('Tanggal','date',toInput(r[0]))+input('Kategori','text',r[1])+input('Judul','text',r[2])+`<label>Detail permasalahan<textarea rows="3" required>${esc(r[3]||'')}</textarea></label><label>Solusi<textarea rows="3" required>${esc(r[4]||'')}</textarea></label>`;if(m==='attendance')return input('Nama karyawan','text',r[0])+input('Tanggal','date',toInput(r[1]))+input('Jam masuk','time',r[2])+input('Jam pulang','time',r[3]);if(m==='reimburse')return input('Tanggal','date',toInput(r[1]))+input('Pemohon','text',r[2])+input('Keterangan','text',r[3])+input('Total biaya','number',String(r[4]||'').replace(/\D/g,''));return input('Tanggal','date',toInput(r[1]))+input('Nama barang','text',r[2])+input('Jumlah','text',r[3])+input('Keperluan','text',r[4])}
function modal(m,i=null){$('#modalTitle').textContent=(i===null?'Buat ':'Edit ')+({attendance:'absensi',work:'laporan pekerjaan',server:'pemeriksaan suhu server',reimburse:'pengajuan reimbursement',request:'pengajuan barang'}[m]);$('#formFields').innerHTML=fields(m,i===null?[]:data[m][i]);$('#modal').dataset.module=m;$('#modal').dataset.index=i===null?'':i;$('#modal').classList.remove('hidden')}
$('#loginBtn').onclick=()=>{if($('#email').value&&$('#password').value){$('#login').classList.add('hidden');$('#app').classList.remove('hidden');sessionStorage.opsAuth='1'}else toast('Masukkan email dan kata sandi.')};if(sessionStorage.opsAuth){$('#login').classList.add('hidden');$('#app').classList.remove('hidden')}$('#logout').onclick=()=>{sessionStorage.removeItem('opsAuth');location.reload()};$$('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));$$('[data-new]').forEach(b=>b.onclick=()=>{show(b.dataset.new);setTimeout(()=>modal(b.dataset.new),100)});$$('.add').forEach(b=>b.onclick=()=>modal(b.closest('.report-page').dataset.module));$('.close').onclick=()=>$('#modal').classList.add('hidden');$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').classList.add('hidden')};$('#saveEntry').onclick=()=>{const m=$('#modal').dataset.module,i=$('#modal').dataset.index,v=$$('#formFields input,#formFields textarea,#formFields select').map(x=>x.value);if(v.some(x=>!x))return toast('Lengkapi semua data terlebih dahulu.');let r;if(m==='work')r=[human(v[0]),...v.slice(1)];else if(m==='server')r=[v[0].split('-').reverse().join('/'),v[1],v[2],v[3]+'°C',v[4]+'%','Normal','RA'];else if(m==='attendance')r=[v[0],human(v[1]),v[2],v[3],'Hadir'];else if(m==='reimburse')r=[i===''?'RB-2026-'+(33+data.reimburse.length):data[m][i][0],human(v[0]),v[1],v[2],'Rp'+Number(v[3]).toLocaleString('id-ID'),i===''?'Menunggu':data[m][i][5]];else r=[i===''?'PB-2026-'+(20+data.request.length):data[m][i][0],human(v[0]),v[1],v[2],v[3],i===''?'Menunggu':data[m][i][5]];i===''?data[m].unshift(r):data[m][Number(i)]=r;render();$('#modal').classList.add('hidden');toast(i===''?'Laporan berhasil disimpan.':'Perubahan tersimpan; rekap bulanan diperbarui.');};$$('.import input').forEach(i=>i.onchange=e=>e.target.files[0]&&toast('File dipilih. Hubungkan parser Excel di backend untuk impor produksi.'));$('#printAll').onclick=()=>printDoc($('.report-page.active-page')?.id);$('#monthlyPrint').onclick=()=>printDoc('monthly');document.addEventListener('click',e=>{const ed=e.target.closest('[data-edit]');if(ed){const[m,i]=ed.dataset.edit.split(':');return modal(m,Number(i))}const p=e.target.closest('[data-print],.print-row');if(p)return printDoc(p.dataset.print||p.closest('.report-page')?.id);const tab=e.target.closest('[data-month-view]');if(tab){$$('[data-month-view]').forEach(x=>x.classList.toggle('active',x===tab));$('#monthlyTemperature').classList.toggle('hidden',tab.dataset.monthView!=='temperature');$('#monthlyWork').classList.toggle('hidden',tab.dataset.monthView!=='worklog')}});$$('[data-copy]').forEach(b=>b.onclick=()=>{navigator.clipboard?.writeText(b.dataset.copy);toast('Panduan konfigurasi: gunakan environment variable '+b.dataset.copy+' di deployment.')});render();
